$out['post:visa-schengen-depuis-conakry-les-5-etapes'] = array(
	'en' => array( 'titre' => 'Schengen visa from Conakry: the 5 steps', 'extrait' => 'Documents, appointment, processing times: how to prepare a strong Schengen visa file from Guinea.', 'contenu' => '<p>The Schengen visa lets you travel to 29 European countries, including France, Belgium, Spain and Italy. Here are the five steps to give yourself the best chance.</p><h2>1. Choose the right consulate</h2><p>Apply to the country where you will spend the most time, or to your first country of entry if the stays are equal.</p><h2>2. Gather the documents</h2><ul><li>Passport valid 3 months after your return, with 2 blank pages</li><li>Recent ID photos</li><li>Bank statements for the last 3 months</li><li>Flight and hotel booking or invitation letter</li><li>Travel insurance covering €30,000</li></ul><h2>3. Book an appointment</h2><p>Slots go fast in high season: plan 6 to 8 weeks ahead.</p><h2>4. Submit the file</h2><p>Arrive on time with the originals and copies sorted in order.</p><h2>5. Track the application</h2><p>With Mondial Express, you follow progress on the <a href="/suivi-de-dossier/">File tracking</a> page or in the app.</p><p>Need help? Discover our <a href="/services/assistance-visa/">visa assistance</a>.</p>' ),
	'es' => array( 'titre' => 'Visado Schengen desde Conakry: los 5 pasos', 'extrait' => 'Documentos, cita, plazos: el método para preparar un expediente de visado Schengen sólido desde Guinea.', 'contenu' => '<p>El visado Schengen permite viajar a 29 países europeos, entre ellos Francia, Bélgica, España e Italia. Estos son los cinco pasos para tener todas las posibilidades a su favor.</p><h2>1. Elegir el consulado correcto</h2><p>Presente su solicitud en el país donde pasará más tiempo, o en el primer país de entrada si las estancias son iguales.</p><h2>2. Reunir los documentos</h2><ul><li>Pasaporte válido 3 meses después del regreso, con 2 páginas en blanco</li><li>Fotos de carné recientes</li><li>Extractos bancarios de los últimos 3 meses</li><li>Reserva de vuelo y hotel o carta de invitación</li><li>Seguro de viaje con cobertura de 30 000 €</li></ul><h2>3. Pedir cita</h2><p>Las citas se agotan en temporada alta: anticípese de 6 a 8 semanas.</p><h2>4. Presentar el expediente</h2><p>Llegue puntual con los originales y las copias ordenados.</p><h2>5. Seguir la solicitud</h2><p>Con Mondial Express, sigue el avance en la página <a href="/suivi-de-dossier/">Seguimiento de expediente</a> o en la aplicación.</p><p>¿Necesita ayuda? Descubra nuestra <a href="/services/assistance-visa/">asistencia de visado</a>.</p>' ),
	'ar' => array( 'titre' => 'تأشيرة شنغن من كوناكري: الخطوات الخمس', 'extrait' => 'الوثائق والموعد والمدة: الطريقة لإعداد ملف قوي لتأشيرة شنغن من غينيا.', 'contenu' => '<p>تتيح تأشيرة شنغن السفر إلى 29 دولة أوروبية، منها فرنسا وبلجيكا وإسبانيا وإيطاليا. إليك الخطوات الخمس لزيادة فرص قبولك.</p><h2>1. اختيار القنصلية المناسبة</h2><p>قدّم طلبك لدى البلد الذي ستقضي فيه أطول مدة، أو لدى أول بلد دخول إذا تساوت المدد.</p><h2>2. جمع الوثائق</h2><ul><li>جواز سفر صالح 3 أشهر بعد العودة مع صفحتين فارغتين</li><li>صور شخصية حديثة</li><li>كشوف حساب بنكي لآخر 3 أشهر</li><li>حجز الطيران والفندق أو شهادة استضافة</li><li>تأمين سفر يغطي 30 000 يورو</li></ul><h2>3. حجز الموعد</h2><p>تنفد المواعيد بسرعة في موسم الذروة: خطّط قبل 6 إلى 8 أسابيع.</p><h2>4. إيداع الملف</h2><p>احضر في الموعد مع الأصول والنسخ مرتّبة.</p><h2>5. متابعة الطلب</h2><p>مع Mondial Express، تتابع التقدم عبر صفحة <a href="/suivi-de-dossier/">متابعة الملف</a> أو في التطبيق.</p><p>تحتاج إلى مساعدة؟ اكتشف <a href="/services/assistance-visa/">المساعدة في التأشيرة</a>.</p>' ),
);
$out['post:bagages-ce-qu-il-faut-savoir-avant-de-partir'] = array(
	'en' => array( 'titre' => 'Luggage: what to know before you leave', 'extrait' => 'Allowance, weight, prohibited items: our tips to avoid bad surprises at Conakry airport.', 'contenu' => '<p>Each airline has its own rules. Always check the conditions shown on your ticket.</p><h2>Checked luggage</h2><p>In economy, the allowance is often 1 or 2 suitcases of 23 kg. Beyond that, extra kilos are expensive: weigh your suitcase before you leave.</p><h2>Cabin luggage</h2><p>Usually 1 bag of 7 to 12 kg and a small bag. Liquids must be in containers of 100 ml maximum.</p><h2>Prohibited items</h2><ul><li>Flammable products</li><li>Power banks in the hold (they go in the cabin)</li><li>Some food products depending on the country of arrival</li></ul><p>Prepare your trip with our <a href="/destinations/">flight deals</a>.</p>' ),
	'es' => array( 'titre' => 'Equipaje: lo que hay que saber antes de salir', 'extrait' => 'Franquicia, peso, objetos prohibidos: nuestros consejos para evitar sorpresas en el aeropuerto de Conakry.', 'contenu' => '<p>Cada aerolínea tiene sus propias reglas. Compruebe siempre las condiciones indicadas en su billete.</p><h2>Equipaje facturado</h2><p>En clase económica, la franquicia suele ser de 1 o 2 maletas de 23 kg. Por encima, los kilos adicionales salen caros: pese su maleta antes de salir.</p><h2>Equipaje de mano</h2><p>Por lo general, 1 bulto de 7 a 12 kg y un bolso pequeño. Los líquidos deben ir en envases de 100 ml como máximo.</p><h2>Objetos prohibidos</h2><ul><li>Productos inflamables</li><li>Baterías externas en bodega (van en cabina)</li><li>Algunos alimentos según el país de llegada</li></ul><p>Prepare su viaje con nuestras <a href="/destinations/">ofertas de billetes</a>.</p>' ),
	'ar' => array( 'titre' => 'الأمتعة: ما يجب معرفته قبل السفر', 'extrait' => 'الوزن المسموح والأغراض الممنوعة: نصائحنا لتجنّب المفاجآت في مطار كوناكري.', 'contenu' => '<p>لكل شركة طيران قواعدها. تحقّق دائمًا من الشروط المذكورة في تذكرتك.</p><h2>الأمتعة المسجّلة</h2><p>في الدرجة الاقتصادية، يُسمح غالبًا بحقيبة أو حقيبتين بوزن 23 كغ. ما يزيد على ذلك مكلف: زِن حقيبتك قبل السفر.</p><h2>حقيبة المقصورة</h2><p>عادةً حقيبة واحدة من 7 إلى 12 كغ وحقيبة صغيرة. يجب أن تكون السوائل في عبوات لا تتجاوز 100 مل.</p><h2>الأغراض الممنوعة</h2><ul><li>المواد القابلة للاشتعال</li><li>البطاريات الخارجية في الأمتعة المسجّلة (مكانها المقصورة)</li><li>بعض المواد الغذائية حسب بلد الوصول</li></ul><p>حضّر رحلتك مع <a href="/destinations/">عروض التذاكر</a>.</p>' ),
);
